    *
    * @Description:
    *   Parse the `avar' table if present.  It need not be, so we return
    *   nothing.
    *
    * @InOut:
    *   face ::
    *     The font face.
    */
   static void
   ft_var_load_avar( TT_Face  face )
   {
     FT_Error   error;
     FT_Stream  stream = FT_FACE_STREAM( face );
     FT_Memory  memory = stream->memory;
     FT_Int     i, j;

     GX_Blend        blend  = face->blend;
     GX_AVarSegment  segment;
     GX_AVarTable    table;

     FT_Long   version;
     FT_Long   axisCount;
     FT_ULong  table_len;

 #ifndef TT_CONFIG_OPTION_NO_BORING_EXPANSION
     FT_ULong  table_offset;
     FT_ULong  store_offset;
     FT_ULong  axisMap_offset;
 #endif


     FT_TRACE2(( "AVAR " ));

     blend->avar_loaded = TRUE;
     error = face->goto_table( face, TTAG_avar, stream, &table_len );
     if ( error )
     {
       FT_TRACE2(( "is missing\n" ));
       return;
     }

 #ifndef TT_CONFIG_OPTION_NO_BORING_EXPANSION
     table_offset = FT_STREAM_POS();
 #endif

     if ( FT_FRAME_ENTER( table_len ) )
       return;

     version   = FT_GET_LONG();
     axisCount = FT_GET_LONG();

     if ( version != 0x00010000L
 #ifndef TT_CONFIG_OPTION_NO_BORING_EXPANSION
          && version != 0x00020000L
 #endif
        )
     {
       FT_TRACE2(( "bad table version\n" ));
       goto Exit;
     }

     FT_TRACE2(( "loaded\n" ));

     if ( axisCount != (FT_Long)blend->mmvar->num_axis )
     {
       FT_TRACE2(( "ft_var_load_avar:"
                   " number of axes in `avar' and `fvar'\n" ));
       FT_TRACE2(( "                  table are different\n" ));
       goto Exit;
     }
